def brute_force(arr: list[int], k: int) -> int:
    n = len(arr)
    max_length = 0
    for i in range(n):
        curr_sum = 0
        for j in range(i, n):
            curr_sum += arr[j]
            if curr_sum == k:
                max_length = max((j-i+1), max_length)
    return max_length


def better_approch(arr: list[int], k: int) -> int:
    n = len(arr)
    max_len = 0
    curr_sum = 0
    l = 0
    for r in range(n):
        curr_sum += arr[r]
        while l < r and curr_sum > k:
            curr_sum -= arr[l]
            l += 1
        if curr_sum == k:
            max_len = max((r-l+1), max_len)
    return max_len

